"""Deterministic, offline showcase assembly; never an additional model turn."""
from html import escape
from showcase_design import COLORS, CSS, enhancements
import event_insights


def render_showcase(b, c, outputs, campaign=None, enabled=(0,1,2,3), decision_notes=None, roundtable=None):
    if b.get('themeCount'):
        from nvidia_event_page import render
        return render(b,c,outputs,campaign,decision_notes,roundtable)
    e = lambda x: escape(str(x), quote=True)
    ticket, floor, progress = enhancements(b, c, outputs, campaign)
    cards = ''.join('<article class="demo" style="--accent:%s" data-number="%02d"><small>EXPERIENCE %02d</small><h3>%s</h3><p><small>YOU DO</small><br>%s</p><strong><small>YOU GET</small><br>%s</strong><div class="demo-foot"><span>%s min / visit</span><span>%s</span></div>%s</article>' %
                    (COLORS[i % len(COLORS)],i+1,i+1,e(t['demo']),e(t.get('action') or 'Participant action pending'),e(t.get('outcome') or 'Visible result pending'),e(c['session']),e(t['topic']),event_insights.design_notes(t))
                    for i,t in enumerate(c['topics']))
    start = sum(int(v)*m for v,m in zip(b['startTime'].split(':'),(60,1)))
    times = ['%02d:%02d' % divmod(t,60) for t in range(start,start+b['duration']-c['session']+1,c['session'])]
    topic_colors = {t['topic']: COLORS[i % len(COLORS)] for i,t in enumerate(c['topics'])}
    visits = {(r['day'],r['booth'],r['start']):r for r in c['schedule']}
    days=[]
    colors=['#c9e8a4','#b0dbea','#e8cba4','#d6b9ec','#edbcbf','#b7ddd0']
    for day in range(1,b['days']+1):
        rows=[]
        for i,booth in enumerate(c['booths']):
            cells=[]
            for time in times:
                r=visits.get((day,booth['booth'],time))
                cells.append('<td style="--topic:'+topic_colors.get(r['topic'] if r else '',COLORS[0])+'">'+('<details><summary><b>'+e(r['presenter'])+'</b><span>'+e(r['demo'])+'</span></summary><p>'+e(r['start'])+'–'+e(r['end'])+' · '+e(r['attendees'])+' attendees</p><p>'+e(r.get('presenterExpertise','Topic specialist'))+'</p></details>' if r else '<span class="free">Available</span>')+'</td>')
            rows.append('<tr style="--topic:'+colors[i%len(colors)]+'"><th>'+e(booth['booth'])+'<span>'+e(booth['topic'])+'</span></th>'+''.join(cells)+'</tr>')
        days.append('<details class="day"'+(' open' if day==1 else '')+'><summary>Day '+str(day)+' · '+e(b['startTime'])+' start</summary><div class="scroll"><table><thead><tr><th>BOOTH / TIME</th>'+''.join('<th>'+e(t)+'</th>' for t in times)+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></details>')
    mail=('<div class="mail"><div class="mailbar">✉ &nbsp; INVITATION DRAFT <span>Not sent</span></div><dl><dt>To</dt><dd>[Attendee]</dd><dt>Subject</dt><dd>'+e(campaign['subject'])+'</dd></dl><div class="mailbody">'+e(campaign['body'])+'</div></div>') if campaign else '<p class="pending">Morgan’s invitation will appear here after the handoff.</p>'
    introduction = '<p class="event-introduction">'+e(outputs.get('0','Your crew is preparing the event brief.'))+'</p>'
    ready=lambda stage: 'Not selected' if stage not in enabled else 'Needs detail' if stage == 1 and str(stage) in outputs and not all(t.get('action') and t.get('outcome') for t in c['topics']) else 'Ready' if str(stage) in outputs else 'Pending'
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>BaC · '''+e(b['city'])+'''</title><style>
*{box-sizing:border-box}body{margin:0;background:#0c141b;color:#eef4f6;font:15px/1.6 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:36px}header{padding:32px;background:radial-gradient(ellipse at right top,#3a592c,transparent 65%),#18242d;border:1px solid #3e5145;border-radius:18px}small,.eyebrow{font-size:11px;letter-spacing:2px;color:#b2df71}h1{font-size:clamp(32px,5vw,58px);letter-spacing:-2px;line-height:1.1;margin:18px 0}h2{font-size:25px;margin:0}h3{font-size:21px;line-height:1.3}p{color:#bac9d1}.facts{display:flex;flex-wrap:wrap;gap:28px;margin-top:25px}.facts b{display:block;font-size:27px}.facts span{color:#bac9d1;font-size:12px}.section{margin-top:38px}.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.badge{border:1px solid #567242;border-radius:20px;padding:3px 12px;color:#c7e6a0;font-size:12px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.demo{padding:24px;border:1px solid #3b4e58;border-radius:14px;background:linear-gradient(150deg,#21343d,#15212b)}.demo strong{color:#c7e6a0;font-size:14px}.day{border:1px solid #3b4e58;border-radius:10px;margin:12px 0;overflow:hidden}.day>summary{padding:16px;cursor:pointer;background:#1a2933;font-weight:600}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #34434d;padding:12px;min-width:155px;vertical-align:top}thead th{background:#1b2b36;color:#cbd6dd}tbody th{background:#192831;position:sticky;left:0;min-width:110px;border-left:4px solid var(--topic)}th span,td span{display:block;margin-top:6px}td{background:color-mix(in srgb,var(--topic) 13%,#111c24)}td b{color:var(--topic)}td summary{cursor:pointer}td p{font-size:12px}.free{color:#7a8d9b}.mail{background:#f6f8fa;color:#172832;border-radius:14px;overflow:hidden;border:1px solid #647782}.mailbar{background:#e3eaf0;padding:16px 24px;font-size:12px;font-weight:700;letter-spacing:1px}.mailbar span{float:right;color:#526977}dl{display:grid;grid-template-columns:65px 1fr;padding:10px 24px;border-bottom:1px solid #ced8df}dt{color:#71818b}dd{margin:0 0 10px;font-weight:600}.mailbody{padding:18px 28px 32px;white-space:pre-wrap;font:16px/1.8 system-ui}.pending{padding:24px;border:1px dashed #536773;border-radius:12px}footer{color:#90a3b1;font-size:12px;margin-top:32px}@media(max-width:600px){main{padding:16px}header{padding:24px}.facts{gap:18px}.sectionhead{align-items:start}h2{font-size:21px}}
'''+CSS+event_insights.CSS+'''</style></head><body><main><header><div class="eyebrow">BUILD-A-CLAW / EVENT SHOWCASE</div><h1>'''+e(b['city'])+'''<br>Meet your next agents.</h1>'''+introduction+ticket+'''<div class="facts">'''+''.join('<div><b>'+e(v)+'</b><span>'+label+'</span></div>' for v,label in [(b['attendees'],'attendees'),(c['boothCount'],'booths'),(c['session'],'minutes / demo'),(b['days'],'days')])+'''</div></header>'''+progress+event_insights.insights(b,c,decision_notes)+'''<section class="section"><div class="sectionhead"><h2>01 / Try it. See it.</h2><span class="badge">Dylan · '''+ready(1)+'''</span></div>'''+'<div class="cards">'+cards+'</div>'+'''</section>'''+floor+'''<section class="section"><div class="sectionhead"><h2>03 / Your booth timetable</h2><span class="badge">Alex · '''+ready(2)+'''</span></div><p>'''+('Same assignments as the Excel rota.' if '2' in outputs else 'Calculated preview · awaiting the operations handoff.')+''' Click a session for details. Presenter numbers are unassigned staffing slots.</p>'''+''.join(days)+'''</section><section class="section"><div class="sectionhead"><h2>04 / You’re invited</h2><span class="badge">Morgan · '''+ready(3)+'''</span></div>'''+mail+'''</section>'''+event_insights.reflections(roundtable)+'''<footer>Agent-authored demo and invitation copy · timetable calculated and page assembled by the studio. Date, venue and recipient details need organizer review. No messages sent.</footer></main></body></html>'''
